-- Florida Poly Dining snapshot from the supplied PDF, collected 2026-11-15.
-- MariaDB 11.8+ required. Reimporting this exact snapshot does not duplicate rows.
-- No credentials, invented prices, or fabricated embeddings are included.
SET NAMES utf8mb4;
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION,NO_BACKSLASH_ESCAPES';
CREATE DATABASE IF NOT EXISTS flpoly_dining CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
USE flpoly_dining;
CREATE TABLE IF NOT EXISTS sources (
 id INT PRIMARY KEY, filename VARCHAR(255) NOT NULL, collected_on DATE NOT NULL,
 source_url VARCHAR(500) NOT NULL, notes TEXT NOT NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS restaurants (
 id INT PRIMARY KEY, name VARCHAR(150) NOT NULL, building VARCHAR(150) NOT NULL,
 address VARCHAR(255) NOT NULL, menu_status VARCHAR(50) NOT NULL,
 buffet_admission_usd DECIMAL(7,2) NULL, price_provenance VARCHAR(100) NULL,
 source_id INT NOT NULL, source_page INT NOT NULL,
 FOREIGN KEY (source_id) REFERENCES sources(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS restaurant_context (
 restaurant_id INT PRIMARY KEY, source_page INT NOT NULL, context_text LONGTEXT NOT NULL,
 FOREIGN KEY (restaurant_id) REFERENCES restaurants(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS menu_items (
 id INT PRIMARY KEY, restaurant_id INT NOT NULL, category VARCHAR(150) NOT NULL,
 name VARCHAR(255) NOT NULL, portion_text VARCHAR(255) NOT NULL,
 calories_text VARCHAR(255) NOT NULL, dietary_tags VARCHAR(50) NULL,
 item_price_usd DECIMAL(7,2) NULL, price_text VARCHAR(100) NOT NULL,
 description TEXT NULL, meal_context VARCHAR(100) NULL,
 category_reliable BOOLEAN NOT NULL, likely_source_error BOOLEAN NOT NULL,
 source_id INT NOT NULL, source_page INT NOT NULL,
 KEY restaurant_category (restaurant_id,category), KEY item_name (name),
 FOREIGN KEY (restaurant_id) REFERENCES restaurants(id),
 FOREIGN KEY (source_id) REFERENCES sources(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rag_chunks (
 chunk_id CHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
 restaurant_id INT NULL, menu_item_id INT NULL, content LONGTEXT NOT NULL,
 source_id INT NOT NULL, source_page INT NOT NULL,
 FOREIGN KEY (restaurant_id) REFERENCES restaurants(id),
 FOREIGN KEY (menu_item_id) REFERENCES menu_items(id),
 FOREIGN KEY (source_id) REFERENCES sources(id)
) ENGINE=InnoDB;
-- Indexed vectors must be NOT NULL. Keep pending chunks separately until embedded.
-- 768 dimensions: intended for local nomic-embed-text; validate actual output before insertion.
CREATE TABLE IF NOT EXISTS rag_embeddings (
 chunk_id CHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
 model VARCHAR(255) NOT NULL, embedding VECTOR(768) NOT NULL,
 VECTOR INDEX vector_cosine (embedding) DISTANCE=cosine
) ENGINE=InnoDB;
START TRANSACTION;
ON DUPLICATE KEY UPDATE id=VALUES(id);
ON DUPLICATE KEY UPDATE id=VALUES(id);
Hours — Hours of Operation page, week Nov 15–21, 2026: Sun 11:00am–7:30pm (Brunch 11:00am–2:00pm, Dinner 4:30–7:30pm); Mon–Fri 7:00am–8:30pm
(Breakfast 7:00–9:30am, Lunch 11:00am–2:00pm, Dinner 4:30–8:30pm); Sat 11:00am–7:30pm (Brunch 11:00am–2:00pm, Dinner 4:30–7:30pm).
Hours — location page, same week (conflicts with the Hours page): Nov 15 1:00–9:30pm; Mon Nov 16 Closed; Tue Nov 17 8:00am–9:30pm; Wed Nov 18
9:00am–10:30pm; Thu Nov 19 Closed; Fri Nov 20 6:00am–7:30pm; Sat Nov 21 10:00am–6:30pm.
Meal times, Nov 1–13, 2026 (as shown on the menu pages): Breakfast Mon–Fri 7:00–9:30am; Brunch Sat/Sun 11:00am–2:00pm; Lunch Mon–Fri 11:00am–2:00pm;
Dinner 4:30–7:30pm. Note: the Nov 15–21 Hours page instead gives weekday dinner to 8:30pm.
Services: Dine In, Takeout. Payment: Cash, Credit Card, Dining Dollars, Meal Swipe.
Coverage: all 36 meals from Nov 1–13, 2026 were checked (Sun/Sat: brunch + dinner; Mon–Fri: breakfast + lunch + dinner). 27 meals loaded cleanly with station
grouping; 9 meals loaded as a flat set of items repeated under every station heading, so station assignment for those meals is unreliable — their items are listed
separately under “Glitched-meal items”. The 9 glitched meals: Nov 9 lunch; Nov 10 lunch and dinner; Nov 11 lunch and dinner; Nov 12 lunch and dinner; Nov 13 lunch
and dinner. Nov 11 breakfast was unusually sparse on the site: only 3 items (Scrambled Eggs, Hard Boiled Eggs, Ham and Cheese Scramble). Nov 9 dinner’s first-read
full menu was not fully transcribed before the page changed on re-check; its items are included only where they also appear on other clean days.
Deduplicated menu, Nov 1–13, 2026: 334 station listings + 79 glitched-meal listings = 413 listings, 401 distinct item names. (The browser report estimated “approx. 390”
distinct names; 401 is the count of distinct names in the report text itself.)'),
